import{_ as e,o as a,c as s,af as l}from"./chunks/framework.BSym9njW.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"00-environment/xdna2-npu.md","filePath":"en/00-environment/xdna2-npu.md","lastUpdated":1789547203000}'),n={name:"00-environment/xdna2-npu.md"};function i(d,t,o,r,c,h){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h2 id="ryzen-ai-xdna2-hardware" tabindex="-1">Ryzen AI XDNA2 Hardware <a class="header-anchor" href="#ryzen-ai-xdna2-hardware" aria-label="Permalink to &quot;Ryzen AI XDNA2 Hardware&quot;">​</a></h2><p>This page covers the hardware needed for <strong>FastFlowLM / Lemonade NPU</strong>. NPU inference uses <strong>XDNA2</strong> and is independent of the <a href="/hello-rocm/00-environment/">ROCm GPU stack</a>: GPU tutorials use the iGPU (<code>gfx1151</code> on Strix Halo); NPU tutorials use <code>/dev/accel/accel0</code>.</p><blockquote><p>See also: <a href="https://lemonade-server.ai/flm_npu_linux.html" target="_blank" rel="noreferrer">Lemonade Linux + FLM</a> · <a href="https://fastflowlm.com/docs/install_lin/" target="_blank" rel="noreferrer">FastFlowLM Linux</a></p></blockquote><hr><h3 id="_1-supported-processors" tabindex="-1">1. Supported processors <a class="header-anchor" href="#_1-supported-processors" aria-label="Permalink to &quot;1. Supported processors&quot;">​</a></h3><p>FastFlowLM NPU LLMs on Linux require <strong>XDNA2</strong>. XDNA1 cannot load the NPU2 weights used in these tutorials.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Family</th><th style="text-align:left;">Codename</th><th style="text-align:left;">NPU</th><th style="text-align:left;">This tutorial</th></tr></thead><tbody><tr><td style="text-align:left;">Ryzen AI Max 300</td><td style="text-align:left;">Strix Halo (e.g. MAX+ 395, gfx1151)</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;"><strong>Primary</strong>; sample host is GMKtec EVO-X2</td></tr><tr><td style="text-align:left;">Ryzen AI 300</td><td style="text-align:left;">Kraken Point, Strix Point</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">Supported; official Gemma 4 benches often use Kraken</td></tr><tr><td style="text-align:left;">Ryzen AI 400</td><td style="text-align:left;">Gorgon Point</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">Supported</td></tr><tr><td style="text-align:left;">Z2 Extreme</td><td style="text-align:left;">Handheld</td><td style="text-align:left;">XDNA2</td><td style="text-align:left;">Supported</td></tr><tr><td style="text-align:left;">Ryzen AI 7000 / 8000 / 200</td><td style="text-align:left;">Phoenix / Hawk Point</td><td style="text-align:left;"><strong>XDNA1</strong></td><td style="text-align:left;"><strong>Not supported</strong> for NPU LLMs</td></tr></tbody></table><p>The Strix Halo iGPU is <strong>gfx1151</strong>. Lemonade <code>llamacpp:rocm</code> / <code>llamacpp:vulkan</code> use that iGPU and <strong>do not</strong> occupy <code>/dev/accel</code>.</p><hr><h3 id="_2-runtime-stack" tabindex="-1">2. Runtime stack <a class="header-anchor" href="#_2-runtime-stack" aria-label="Permalink to &quot;2. Runtime stack&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Item</th><th style="text-align:left;">Requirement</th></tr></thead><tbody><tr><td style="text-align:left;">NPU firmware</td><td style="text-align:left;"><strong>1.1.0.0 or later</strong> (validated at 1.1.2.65)</td></tr><tr><td style="text-align:left;">Kernel + driver</td><td style="text-align:left;">Kernel 7.0+ with in-tree <code>amdxdna</code>, or <code>amdxdna-dkms</code> on Ubuntu 24.04</td></tr><tr><td style="text-align:left;">Userspace</td><td style="text-align:left;"><code>libxrt-npu2</code> + FastFlowLM (<code>flm</code>)</td></tr><tr><td style="text-align:left;">memlock</td><td style="text-align:left;"><code>ulimit -l</code> = <code>unlimited</code></td></tr><tr><td style="text-align:left;">Device node</td><td style="text-align:left;"><code>/dev/accel/accel0</code>; user in <code>render</code> (also add <code>video</code>)</td></tr><tr><td style="text-align:left;">IOMMU</td><td style="text-align:left;">cmdline has both <code>amd_iommu=on</code> and <code>iommu=pt</code></td></tr></tbody></table><hr><h3 id="_3-check-the-machine" tabindex="-1">3. Check the machine <a class="header-anchor" href="#_3-check-the-machine" aria-label="Permalink to &quot;3. Check the machine&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lspci</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -nn</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">grep</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -iE</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &#39;processing|display|npu&#39;</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ls</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -l</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /dev/accel/accel0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>On Strix Halo the NPU PCI ID is commonly <code>1022:17f0</code>. After <code>flm</code> is installed:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">flm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> validate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>You should see the NPU device, firmware <strong>1.1.x</strong>, and memlock infinity / unlimited.</p><hr><h3 id="_4-relationship-to-rocm-gpu" tabindex="-1">4. Relationship to ROCm GPU <a class="header-anchor" href="#_4-relationship-to-rocm-gpu" aria-label="Permalink to &quot;4. Relationship to ROCm GPU&quot;">​</a></h3><ul><li><strong>They can coexist</strong>: ROCm for GPU (vLLM / Ollama / llama.cpp), FastFlowLM for NPU.</li><li><strong>Do not mix env vars</strong>: <code>source /opt/rocm</code> then <code>flm</code> often becomes <code>No such device with index &#39;0&#39;</code>. Unset <code>ROCM_PATH HIP_PATH LD_LIBRARY_PATH</code> first.</li><li><strong>Unified memory</strong>: NPU and large GGUF share system RAM. Gemma 4 E4B NPU is ~9 GiB; Qwen3.6-35B-A3B NPU is ~29 GiB. Keep one large model resident.</li><li><strong>One NPU client at a time</strong>: if Lemonade has loaded an FLM model, do not also <code>flm serve</code>.</li></ul><p>Next: <a href="./fastflowlm">FastFlowLM environment</a> · <a href="./lemonade">Lemonade environment</a></p>`,21)])])}const g=e(n,[["render",i]]);export{m as __pageData,g as default};
